        .@"generic_enum" => if (role == .@"members") 3 else null,
        .@"match" => if (role == .@"arms") 2 else null,
        .@"variant_pattern" => if (role == .@"bindings") 2 else null,
        .@"block" => if (role == .@"stmts") 1 else null,
        .@"captures" => if (role == .@"caps") 1 else null,
        .@"call" => if (role == .@"args") 2 else null,
        .@"builtin" => if (role == .@"args") 2 else null,
        .@"inst" => if (role == .@"args") 2 else null,
        .@"array" => if (role == .@"elems") 1 else null,
        .@"generic_inst" => if (role == .@"args") 2 else null,
        else => null,
    };
}

/// The slot role at `slot` of nodes of `kind`.
fn roleAt(kind: Tag, slot: usize) ?Role {
    return switch (kind) {
        .@"use" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"fun" => switch (slot) {
            1 => .@"name",
            2 => .@"tparams",
            3 => .@"params",
            4 => .@"returns",
            5 => .@"body",
            else => null,
        },
        .@"sub" => switch (slot) {
            1 => .@"name",
            2 => .@"tparams",
            3 => .@"params",
            4 => .@"fails",
            5 => .@"body",
            else => null,
        },
        .@"lambda" => switch (slot) {
            1 => .@"captures",
            2 => .@"params",
            3 => .@"body",
            else => null,
        },
        .@"struct" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"enum" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"errors" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"generic_struct" => switch (slot) {
            1 => .@"name",
            2 => .@"tparams",
            else => null,
        },
        .@"generic_enum" => switch (slot) {
            1 => .@"name",
            2 => .@"tparams",
            else => null,
        },
        .@"type" => switch (slot) {
            1 => .@"name",
            2 => .@"type",
            else => null,
        },
        .@"test" => switch (slot) {
            1 => .@"name",
            2 => .@"body",
            else => null,
        },
        .@"pub" => switch (slot) {
            1 => .@"decl",
            else => null,
        },
        .@"extern" => switch (slot) {
            1 => .@"name",
            2 => .@"type",
            else => null,
        },
        .@"extern_fun" => switch (slot) {
            1 => .@"name",
            2 => .@"params",
            3 => .@"returns",
            else => null,
        },
        .@"extern_sub" => switch (slot) {
            1 => .@"name",
            2 => .@"params",
            else => null,
        },
        .@"drop_decl" => switch (slot) {
            1 => .@"params",
            2 => .@"body",
            else => null,
        },
        .@"labeled" => switch (slot) {
            1 => .@"label",
            2 => .@"stmt",
            else => null,
        },
        .@":" => switch (slot) {
            1 => .@"name",
            2 => .@"type",
            else => null,
        },
        .@"default" => switch (slot) {
            1 => .@"name",
            2 => .@"type",
            3 => .@"value",
            else => null,
        },
        .@"valued" => switch (slot) {
            1 => .@"name",
            2 => .@"value",
            else => null,
        },
        .@"variant" => switch (slot) {
            1 => .@"name",
            2 => .@"params",
            else => null,
        },
        .@"set" => switch (slot) {
            1 => .@"op",
            2 => .@"target",
            3 => .@"type",
            4 => .@"value",
            else => null,
        },
        .@"drop" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"if" => switch (slot) {
            1 => .@"cond",
            2 => .@"then",
            3 => .@"else",
            else => null,
        },
        .@"as" => switch (slot) {
            1 => .@"value",
            2 => .@"name",
            else => null,
        },
        .@"while" => switch (slot) {
            1 => .@"cond",
            2 => .@"step",
            3 => .@"body",
            4 => .@"else",
            else => null,
        },
        .@"for" => switch (slot) {
            1 => .@"mode",
            2 => .@"var",
            3 => .@"index",
            4 => .@"source",
            5 => .@"body",
            6 => .@"else",
            else => null,
        },
        .@"match" => switch (slot) {
            1 => .@"subject",
            else => null,
        },
        .@"arm" => switch (slot) {
            1 => .@"pattern",
            2 => .@"body",
            else => null,
        },
        .@"range_pattern" => switch (slot) {
            1 => .@"lo",
            2 => .@"hi",
            else => null,
        },
        .@"variant_pattern" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"enum_lit" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"return" => switch (slot) {
            1 => .@"value",
            else => null,
        },
        .@"break" => switch (slot) {
            1 => .@"value",
            2 => .@"label",
            else => null,
        },
        .@"continue" => switch (slot) {
            1 => .@"label",
            else => null,
        },
        .@"defer" => switch (slot) {
            1 => .@"body",
            else => null,
        },
        .@"errdefer" => switch (slot) {
            1 => .@"body",
            else => null,
        },
        .@"raw_block" => switch (slot) {
            1 => .@"body",
            else => null,
        },
        .@"propagate" => switch (slot) {
            1 => .@"value",
            else => null,
        },
        .@"propagate_none" => switch (slot) {
            1 => .@"value",
            else => null,
        },
        .@"catch" => switch (slot) {
            1 => .@"value",
            2 => .@"name",
            3 => .@"handler",
            else => null,
        },
        .@"cap_clone" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"cap_move" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"cap_weak" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"cap_read" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"cap_write" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"call" => switch (slot) {
            1 => .@"callee",
            else => null,
        },
        .@"builtin" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"member" => switch (slot) {
            1 => .@"object",
            2 => .@"name",
            else => null,
        },
        .@"index" => switch (slot) {
            1 => .@"object",
            2 => .@"index",
            else => null,
        },
        .@"inst" => switch (slot) {
            1 => .@"object",
            else => null,
        },
        .@"array_fill" => switch (slot) {
            1 => .@"size",
            2 => .@"value",
            else => null,
        },
        .@"kwarg" => switch (slot) {
            1 => .@"name",
            2 => .@"value",
            else => null,
        },
        .@"+" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"-" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"*" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"/" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"%" => switch (slot) {
            1 => .@"left",
