            else => null,
        },
        .@"==" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"!=" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"<" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@">" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"<=" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@">=" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"&" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"|" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"^" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"<<" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@">>" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"??" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"and" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"or" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@".." => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"neg" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"not" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"move" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"read" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"write" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"clone" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"share" => switch (slot) {
            1 => .@"operand",
            else => null,
        },
        .@"weak" => switch (slot) {
            1 => .@"operand",
            else => null,
