        .@"optional" => switch (slot) {
            1 => .@"type",
            else => null,
        },
        .@"error_union" => switch (slot) {
            1 => .@"type",
            else => null,
        },
        .@"borrow_read" => switch (slot) {
            1 => .@"type",
            else => null,
        },
        .@"borrow_write" => switch (slot) {
            1 => .@"type",
            else => null,
        },
        .@"shared" => switch (slot) {
